window.AUTH=window.AUTH||{};window.AUTH["23-726"]={"d":"23-726","id":"2023/23-726","n":"Moyle v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioners Mike Moyle, et al. (as to 23-726)","date":"2024-02-20","url":"https://www.supremecourt.gov/DocketPDF/23/23-726/300916/20240220130216550_Moyle%20v%20United%20States%20_%20Legislature%20Opening%20Merits%20Brief.pdf","side":"pet","n":83},{"k":"petitioner","label":"Brief of petitioner Idaho (as to 23-727)","date":"2024-02-20","url":"https://www.supremecourt.gov/DocketPDF/23/23-726/301167/20240222152045736_Main%20Document%2023-727.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondent United States","date":"2024-03-21","url":"https://www.supremecourt.gov/DocketPDF/23/23-726/305680/20240321205817124_23-726bsUnitedStates.pdf","side":"res","n":104},{"k":"reply","label":"Reply of petitioners Mike Moyle, et al.","date":"2024-04-11","url":"https://www.supremecourt.gov/DocketPDF/23/23-726/307360/20240411125751388_23-726%20Moyle%20v%20United%20States%20Legislature%20Reply%20Brief.pdf","side":"pet","n":46},{"k":"reply","label":"Reply of petitioner Idaho","date":"2024-04-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-726/307435/20240412104107924_23-727%20Reply%20Brief.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r53_l5gm.pdf","tr":true,"items":[{"t":"case","label":"Ala. Ass’n of Realtors v. Dep’t of Health & Hum. Servs.","cite":"141 S. Ct. 2485","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/2485/","sc":1,"by":{"0":"48","1":"22, 38","3":"23"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"23, 35"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"ar":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Arrowpoint Cap. Corp. v. Arrowpoint Asset Mgmt.","cite":"793 F.3d 313","y":2015,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/793/313/","by":{"0":"14"}},{"t":"case","label":"Barsky v. Bd. of Regents","cite":"347 U.S. 442","y":1954,"id":"scdb/1953-067","sc":1,"sum":"The New York law, on its face or as so construed and applied, does not violate the Due Process Clause of the Fourteenth Amendment. Pp. 443-456. _ (a) The decision of the highest state court that a violation of 2 U. S. C. § 192, though not a crime under New York law, was a \"crime\" within the meaning of § 6514-2 (b) of the State Education Law, is conclusive here.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"55"}},{"t":"case","label":"Berger v. N.C. State Conf. of the NAACP","cite":"597 U.S. 179","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/179/","sc":1,"op":1,"by":{"0":"12"}},{"t":"case","label":"Biden v. Missouri","cite":"142 S. Ct. 647","y":2022,"id":"2021/21a240","sc":1,"sum":"The Court grants the applications to stay the two injunctions barring the Secretary of Health and Human Services’ regulation requiring facilities that participate in Medicare and Medicaid to ensure that their employees are vaccinated against COVID–19.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21","2":"4, 45"}},{"t":"case","label":"Biden v. Nebraska","cite":"143 S. Ct. 2355","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39, 43, 45","1":"35","2":"49","3":"17, 23, 24"}},{"t":"case","label":"Bond v. United States","cite":"564 U.S. 211","y":2011,"id":"2010/09-1227","sc":1,"sum":"The Court held that a defendant, convicted under a federal statute, has a right to challenge his/her conviction based on the unconstitutionality of the statute.","sumSrc":"Oyez","by":{"0":"54"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"54"}},{"t":"case","label":"Bradley v. Sch. Bd. of Richmond","cite":"416 U.S. 696","y":1974,"id":"1973/72-1322","sc":1,"sum":"Section 718 can be applied to attorneys' services that were rendered before that provision was enacted, in a situation like the one here involved where the propriety of the fee award was pending resolution on appeal when the statute became law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8"}},{"t":"case","label":"Bryan v. Rectors & Visitors of Univ. of Va.","cite":"95 F.3d 349","y":1996,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/95/349/","by":{"0":"27","1":"36","2":"32","3":"5","4":"17"}},{"t":"case","label":"Bryant v. Adventist Health Sys.","cite":"289 F.3d 1162","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/289/1162/","by":{"0":"24, 27","1":"9"}},{"t":"case","label":"Burditt v. U.S. Dep’t of Health & Hum. Servs.","cite":"934 F.2d 1362","y":1991,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/934/1362/","by":{"0":"44","2":"30","3":"18","4":"16"}},{"t":"case","label":"Cal. Coastal Comm’n v. Granite Rock Co.","cite":"480 U.S. 572","y":1987,"id":"1986/85-1200","sc":1,"sum":"The Mining Act of 1872 authorizes a private citizen to enter federal lands to explore for mineral deposits, to perfect a mining claim, and to secure a patent to the land by complying with the requirements of the Act and regulations promulgated thereunder. Appellee Granite Rock Co. holds unpatented mining claims on federally owned lands in a national forest located in California. In accordance with federal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Cannon v. Univ. of Chi.","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"51"}},{"t":"case","label":"Charles C. Steward Mach. Co. v. Davis","cite":"301 U.S. 548","y":1937,"id":"1900-1940/301us548","sc":1,"op":1,"sum":"The Court held that the tax under the Social Security Act was a constitutional exercise of congressional power.","sumSrc":"Oyez","by":{"0":"50, 51"}},{"t":"case","label":"Chamber of Com. of U.S. v. Whiting","cite":"563 U.S. 582","y":2011,"id":"2010/09-115","sc":1,"sum":"The Court held that Arizona laws requiring employers to verify the employment eligibility of their employees through a federal database was not unconstitutional.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Cherukuri v. Shalala","cite":"175 F.3d 446","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/175/446/","by":{"0":"44","1":"36","2":"32"}},{"t":"case","label":"Cipollone v. Liggett Grp., Inc.","cite":"505 U.S. 504","y":1992,"id":"1991/90-1038","sc":1,"sum":"In a complicated 7-to-2 decision, the Court held that federally mandated warnings do not bar smokers from suing manufacturers under state personal-injury laws. The justices ruled that such suits cannot be based on claims that cigarette advertising failed to warn smokers of smoking dangers.","sumSrc":"Oyez","by":{"0":"21, 23, 25, 29, 35","1":"10","3":"2"}},{"t":"case","label":"Crosby v. Nat’l Foreign Trade Council","cite":"530 U.S. 363","y":2000,"id":"1999/99-474","sc":1,"sum":"The Court held that \"the state Act is preempted, and its application unconstitutional, under the Supremacy Clause.\" Justice Souter wrote for the Court that Massachusetts' law created an obstacle to the President's discretion to control economic sanctions against Burma, interfered with Congress's intention to limit economic pressure against the Burmese Government, and was at odds with the President's authority to speak for the United States among the world's nations to develop a comprehensive, multilateral Burma strategy.","sumSrc":"Oyez","by":{"0":"36","1":"23"}},{"t":"case","label":"CSX Transp., Inc. v. Easterwood","cite":"507 U.S. 658","y":1993,"id":"1992/91-790","sc":1,"sum":"Under the FRSA, federal regulations adopted by the Secretary of Transportation pre-empt Easterwood's negligence action only insofar as it asserts that CSX's train was traveling at an excessive speed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Cummings v. Premier Rehab Keller, P.L.L.C.","cite":"142 S. Ct. 1562","y":2022,"id":"2021/20-219","sc":1,"op":2,"sum":"Emotional distress damages are not recoverable in a private action to enforce either the Rehabilitation Act of 1973 or the Affordable Care Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"48, 49","2":"45, 46"}},{"t":"case","label":"De Veau v. Braisted","cite":"363 U.S. 144","y":1960,"id":"1959/71","sc":1,"sum":"This section does not violate the Supremacy Clause of the Constitution by conflicting invalidly with the National Labor Relations Act or the Labor-Management Reporting and Disclosure Act of. 1959; it does not violate the Due Process Clause of the Fourteenth Amendment; and it is not an ex post facto law or bill of attainder forbidden by Article I, § 10 of the Constitution. Pp. 144-161. 5 N. Y. 2d 236, 157 N. E. 2d …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 34","3":"2, 16"}},{"t":"case","label":"Dep’t of Transp. v. Ass’n of Am. R.R.","cite":"575 U.S. 43","y":2015,"id":"2014/13-1080","sc":1,"sum":"The Court held that for purposes of the validity of metrics and standards, Amtrak is a governmental entity.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Dobbs v. Jackson Women’s Health Org.","cite":"142 S. Ct. 2228","y":2022,"id":"2021/19-1392","sc":1,"op":3,"ar":4,"sum":"The Constitution does not confer a right to abortion; Roe v. Wade, 410 U. S. 113, and Planned Parenthood of Southeastern Pa. v. Casey, 505 U. S. 833, are overruled; the authority to regulate abortion is returned to the people and their elected representatives.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"1, 8, 25, 37, 46, 55, 56","1":"3, 6, 11, 40","2":"3, 15, 47, 48","3":"26, 27"}},{"t":"case","label":"Draper v. Chiapuzio","cite":"9 F.3d 1391","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/9/1391/","by":{"0":"35","1":"11"}},{"t":"case","label":"Dubin v. United States","cite":"143 S. Ct. 1557","y":2023,"id":"2022/22-10","sc":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"43"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"31, 35, 37","3":"5, 11"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"31, 39","2":"48","3":"23"}},{"t":"case","label":"Fla. Lime & Avocado Growers, Inc. v. Paul","cite":"373 U.S. 132","y":1963,"id":"1962/45","sc":1,"sum":"The Court held that federal law will preempt a state law if it is physically impossible to comply with both laws.","sumSrc":"Oyez","by":{"0":"36","1":"23"}},{"t":"case","label":"Gade v. Nat’l Solid Wastes Mgmt. Ass’n","cite":"505 U.S. 88","y":1992,"id":"1991/90-1676","sc":1,"sum":"The judgment is affirmed. 918 F. 2d 671, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"op":1,"ar":2,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"0":"41, 45, 55","1":"10","2":"47","3":"1, 24, 26","4":"3"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"46","3":"9"}},{"t":"case","label":"Harris v. McRae","cite":"448 U.S. 297","y":1980,"id":"1979/79-1268","sc":1,"op":1,"sum":"The Court held that states participating in the Medicaid program were not obligated to fund medically necessary abortions under Title XIX.","sumSrc":"Oyez","by":{"0":"10, 33"}},{"t":"case","label":"Harry v. Marchant","cite":"291 F.3d 767","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/291/767/","by":{"0":"27, 44","1":"36","3":"5, 8","4":"17"}},{"t":"case","label":"Hillman v. Maretta","cite":"569 U.S. 483","y":2013,"id":"2012/11-1221","sc":1,"sum":"The Court found that the Federal Employees' Group Life Insurance Act preempts a Virginia state law regarding beneficiary designation upon divorce.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Hillsborough County v. Automated Med. Labs., Inc.","cite":"471 U.S. 707","y":1985,"id":"1984/83-1925","sc":1,"sum":"Appellant county's ordinances and implementing regulations are not pre-empted by the federal regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"55"}},{"t":"case","label":"Int’l Molders’ & Allied Workers’ Local Union No. 164 v. Nelson","cite":"799 F.2d 547","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/799/547/","by":{"0":"14"}},{"t":"case","label":"ICC v. Cincinnati, N.O. & T.P. R.","cite":"167 U.S. 479","y":1897,"id":"scdb/1896-212","sc":1,"sum":"Congress has not conferred upon the Interstate Commerce Commission the legislative power of prescribing rates either maximum or minimum or absolute; and, as it did not give the express power to the commission, it did not intend to secure the same result indirectly by empowering that tribunal to determine what in reference to the past was reasonable and just, whether as maximum, minimum or absolute, and then enable …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"39, 48"}},{"t":"case","label":"Kansas v. Garcia","cite":"140 S. Ct. 791","y":2020,"id":"2019/17-834","sc":1,"sum":"A case in which the Court upheld Kansas's prosecution of noncitizens who used stolen social security numbers to gain employment.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"La. Pub. Serv. Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","3":"24"}},{"t":"case","label":"Linder v. United States","cite":"268 U.S. 5","y":1925,"id":"scdb/1924-117","sc":1,"sum":"1. Any provision of an act of Congress ostensibly enacted under power granted by the Constitution, not naturally and reasonably adapted to the effective exercise of such power but solely to the achievement of something plainly within tha power reserved to the States, is invalid and can. not be enforced.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"51"}},{"t":"case","label":"Madsen v. Women’s Health Ctr., Inc.","cite":"512 U.S. 753","y":1994,"id":"1993/93-880","sc":1,"sum":"In a majority opinion authored by Chief Justice William H. Rehnquist, the Court found that the state of Florida could only restrict protesters to the extent necessary to allow the clinic to run and the staff to live in their homes without interference.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Maine v. Thiboutot","cite":"448 U.S. 1","y":1980,"id":"1979/79-838","sc":1,"sum":"Yes to both. Section 1983 encompasses claims based on purely statutory violations of federal law, and section 1988 authorizes attorney's fees to the prevailing party in such actions, whether brought in federal or state court.","sumSrc":"AI-generated brief","by":{"0":"51"}},{"t":"case","label":"Marshall v. E. Carroll Par. Hosp. Serv. Dist.","cite":"134 F.3d 319","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/134/319/","by":{"0":"36, 43","1":"7, 29, 36"}},{"t":"case","label":"Massachusetts v. Mellon","cite":"262 U.S. 447","y":1923,"id":"1900-1940/262us447","sc":1,"op":2,"sum":"The Court held that the administration of federal statutes \"likely to produce addition taxation to be imposed upon a vast number of taxpayers\" was essentially a matter of public and not of individual concern.","sumSrc":"Oyez","by":{"0":"50"}},{"t":"case","label":"Medtronic, Inc. v. Lohr","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"0":"21, 23, 25, 54","1":"10, 19, 25, 37","4":"3"}},{"t":"case","label":"Memphis Ctr. for Reprod. Health v. Slatery","cite":"14 F.4th 409","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/14/409/","sum":"Noting States enacted 90 abortion-related laws in the first half of 2021.","sumSrc":"brief:0","by":{"0":"55"}},{"t":"case","label":"Moses v. Providence Hosp. & Med. Ctrs., Inc.","cite":"561 F.3d 573","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/561/573/","by":{"0":"24","2":"30","4":"16"}},{"t":"case","label":"Murphy v. NCAA","cite":"584 U.S. 453","y":2018,"url":"https://supreme.justia.com/cases/federal/us/584/453/","sc":1,"by":{"0":"36, 38, 49, 53, 56","2":"47","3":"26"}},{"t":"case","label":"Mut. Pharma. Co. v. Bartlett","cite":"570 U.S. 472","y":2013,"id":"2012/12-142","sc":1,"op":1,"sum":"The Court found that federal law preempts state law design-defect claims.","sumSrc":"Oyez","by":{"0":"36","1":"21"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"0":"49, 53, 56","2":"47"}},{"t":"case","label":"NFIB v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"op":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"0":"49, 50, 51, 52"}},{"t":"case","label":"Oklahoma v. U.S. Civil Serv. Comm’n","cite":"330 U.S. 127","y":1947,"id":"scdb/1946-051","sc":1,"sum":".A member of the State Highway Commission of Oklahoma, whose principal employment was in connection with an activity financed in part by loans and grants from a federal agency, served at the same time as Chairman of the Democratic State Central Committee. During his service on the Highway Commission, there was no general election in the State; but he advised with the Governor concerning a dinner sponsored by his …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"op":3,"sum":"Section 6010 does not create in favor of the mentally retarded any substantive rights to \"appropriate treatment\" in the \"least restrictive\" environment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50, 51","1":"11, 20","3":"26","4":"3"}},{"t":"case","label":"Perez v. Mortgage Bankers Ass’n","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"sum":"The Court ruled that federal agencies do not need to engage in a notice-and-comment procedure before significantly altering an interpretation of a rule of agency regulation.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Pharm. Rsch. & Mfrs. of Am. v. Walsh","cite":"538 U.S. 644","y":2003,"id":"2002/01-188","sc":1,"sum":"The Court held, 9-0, that the Pharmaceutical Research and Manufacturers of America had not carried its burden of showing a probability of success on the merits of its Commerce Clause claims and, 6-3, that their showing was insufficient to support a finding that the Medicaid Act pre-empts Maine's Rx Program insofar as it threatens to coerce manufacturers into reducing their prices on non- Medicaid sales.","sumSrc":"Oyez","by":{"0":"28, 30"}},{"t":"case","label":"Philpott v. Essex Cnty. Welfare Bd.","cite":"409 U.S. 413","y":1973,"id":"1972/71-5656","sc":1,"op":1,"sum":"A Social Security Act provision, 42 U. S. C. § 407, which prohibits subjecting federal disability insurance benefits and other benefits to any legal process, bars a State from recovering such benefits retroactively paid to a beneficiary, and in this case no exception can be implied on the ground that if the federal payments had been made monthly there would have been a corresponding reduction in the state payments. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"51","2":"46"}},{"t":"case","label":"Planned Parenthood Great Nw. v. Idaho","cite":"522 P.3d 1132","y":2023,"court":"Idaho","url":"https://www.courtlistener.com/c/P.3d/522/1132/","op":10,"sum":"Noting that the Act “imposes a subjective standard based on the individual physician's good faith medical judgment”.","sumSrc":"opinion","by":{"0":"7, 8, 9, 10, 13, 16, 28, 30","1":"3, 5–6, 15, 31","2":"22","3":"14, 20, 21, 22","4":"8"}},{"t":"case","label":"Reid v. Colorado","cite":"187 U.S. 137","y":1902,"id":"scdb/1902-007","sc":1,"sum":"The transportation of live stock from State to State is a branch of interstate commerce and any specified rule or regulation in respect of such transportation, which Congress may lawfully prescribe or authorize and which may properly be deemed a regulation of such commerce, is paramount throughout the Union.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"54"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"sum":"Consumers who pay a higher price for goods purchased for personal use as a result of antitrust violations sustain an injury in their \"property\" within the meaning of § 4.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Rice v. Santa Fe Elevator Corp.","cite":"331 U.S. 218","y":1947,"id":"scdb/1946-098","sc":1,"op":1,"sum":"1. By the 1931 amendments to §§ 6 and 29 of the United States Warehouse Act, Congress terminated the dual system of regulation provided by the original Act and substituted an exclusive system of federal regulation of warehouses licensed under the Federal Act with reference to the subjects covered thereby, except to the extent that express exceptions in the Federal Act subject certain phases of the business to state …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 54","1":"10, 19","3":"2, 26"}},{"t":"case","label":"Roe v. Wade","cite":"410 U.S. 113","y":1973,"id":"1971/70-18","sc":1,"op":3,"sum":"A case in which the Court struck down several Texas laws that criminalized abortion, holding that laws that impose an undue burden on a woman’s right to seek an abortion violate her fundamental right to privacy under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"7","4":"19"}},{"t":"case","label":"Sackett v. EPA","cite":"143 S. Ct. 1322","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/1322/","sc":1,"sum":"Rejecting Government’s argument that major questions doctrine concerns only agency’s “power to regulate” versus “provision of government benefits”.","sumSrc":"brief:3","by":{"0":"54, 55","3":"26"}},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Shaw v. Delta Air Lines, Inc.","cite":"463 U.S. 85","y":1983,"id":"1982/81-1578","sc":1,"sum":"New York's Human Rights Law forbids discrimination in employee benefit plans on the basis of pregnancy, and its Disability Benefits Law requires employers to pay sick-leave benefits to employees unable to work because of pregnancy. Section 514(a) of the federal Employee Retirement Income Security Act of 1974 (ERISA) provides, with enumerated exceptions, that ERISA shall supersede \"any and all state laws insofar as …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"South Dakota v. Dole","cite":"483 U.S. 203","y":1987,"id":"1986/86-260","sc":1,"sum":"The Court ruled that Congress did not exceed its spending powers or violate the Twenty-First Amendment when it conditioned the award of federal highway funds on states' adoption of a uniform minimum drinking age.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Summers v. Baptist Med. Ctr. Arkadelphia","cite":"91 F.3d 1132","y":1996,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/91/1132/","by":{"0":"27, 43","1":"27, 31","2":"31, 32","4":"17"}},{"t":"case","label":"Texas v. Becerra","cite":"89 F.4th 529","y":2024,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/89/529/","op":1,"by":{"0":"17, 42, 43, 44","1":"4, 18, 24–25, 27, 29, 32–33, 36–37","2":"18, 28, 30","3":"12","4":"16, 17, 18, 19"}},{"t":"case","label":"Townsend v. Swank","cite":"404 U.S. 282","y":1971,"id":"1971/70-5021","sc":1,"op":2,"sum":"Under § 402 (a) (10) of the Social Security Act, a state participating plan under the AFDC program must provide that aid to families with dependent children shall be furnished with reasonable promptness to \"all eligible\" individuals. Since § 406 (a) (2) (B) of the Act makes dependent 18-20-year-olds eligible for benefits whether attending a college or university or a vocational or technical training course, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50, 51","2":"46","3":"25"}},{"t":"case","label":"Utility Air Regul. Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"0":"38, 41, 42, 43, 48","1":"22","3":"24"}},{"t":"case","label":"W. Va. Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Washington v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"sum":"The Court decided that a law banning physician-assisted suicide does not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"49","1":"10, 20","3":"27"}},{"t":"case","label":"West Virginia v. EPA","cite":"142 S. Ct. 2587","y":2022,"id":"2021/20-1530","sc":1,"sum":"Congress did not grant the Environmental Protection Agency in Section 111(d) of the Clean Air Act the authority to devise emissions caps based on the generation shifting approach the Agency took in the Clean Power Plan.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"38, 39, 41, 42, 43, 45, 46","3":"23, 24"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"2, 25, 43","1":"21"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"const","label":"Amendment X","clauses":[["tenth-amendment","Tenth Amendment"]],"text":"The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.","by":{"0":"54","2":"47"}},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"0":"47"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"0":"48"}},{"t":"reg","label":"Exec. Order No. 13952, 85 Fed. Reg. 62187","url":"https://www.govinfo.gov/link/fr/85/62187","by":{"0":"7"}},{"t":"reg","label":"Exec. Order No. 14076, 87 Fed. Reg. 42053","url":"https://www.govinfo.gov/link/fr/87/42053","by":{"0":"11, 42, 46","1":"12"}},{"t":"case","label":"Abbott v. Perez","cite":"138 S. Ct. 2305","y":2018,"id":"2017/17-586","sc":1,"sum":"The Court decided that the district court erred in disregarding the presumption of good faith on the part of the Texas Legislature and improperly reversed the burden of proof in requiring the state to show a lack of discriminatory intent in adopting new districting plans; the Court also held that one of the state house districts at issue was an impermissible racial gerrymander.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Abigail Alliance for Better Access to Development Drugs v. von Eschenbach","cite":"495 F.3d 696","y":2007,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/495/696/","by":{"1":"30"}},{"t":"case","label":"Altria Group, Inc. v. Good","cite":"555 U.S. 70","y":2008,"id":"2008/07-562","sc":1,"sum":"The Court held that the Federal Cigarette Labeling and Advertising Act did not preempt all claims related to \"smoking and health\" under the Maine Unfair Trade Practices Act.","sumSrc":"Oyez","by":{"1":"19","4":"3"}},{"t":"case","label":"Arlington Central School District Board of Education v. Murphy","cite":"548 U.S. 291","y":2006,"id":"2005/05-18","sc":1,"op":2,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that IDEA did not authorize reimbursement of expert fees. \"While authorizing the award of reasonable attorney's fees, the Act contains detailed provisions that are designed to ensure that such awards are indeed reasonable,\" Justice Alito wrote. \"The absence of any comparable provisions relating to expert fees strongly suggests that recovery of expert fees is not authorized.\" Justice Alito went on to write that the case was made even simpler by the fact that, as an exercise of Congress's Spending Clause power, any provision requiring reimbursement of expert fees would have had to be \"unambiguous,\" which it clearly was not.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Baker v. Adventist Health, Inc.","cite":"260 F.3d 987","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/260/987/","by":{"1":"29","2":"37","4":"17"}},{"t":"case","label":"Bates v. Dow Agrosciences LLC","cite":"544 U.S. 431","y":2005,"id":"2004/03-388","sc":1,"sum":"The Court held that the peanut farmers could sue Dow in state court.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"sum":"The Bank Secrecy Act’s $10,000 maximum penalty for the nonwillful failure to file a compliant report accrues on a per-report, not a per-account, basis.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"33"}},{"t":"case","label":"Brooker v. Desert Hospital Corp.","cite":"947 F.2d 412","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/947/412/","by":{"1":"36"}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"sum":"Section 204 (a) (1) of the Social Security Act (Act) authorizes the Secretary of the Department of Health, Education, and Welfare to recoup erroneous overpayments made to a beneficiary under the old-age, survivors', or disability insurance programs by decreasing future payments to which the overpaid person is entitled. However, § 204 (b) commands that \"there shall be no adjustment of payments to, or recovery by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"California v. United States","cite":"2008 WL 744840","y":2008,"court":"N.D. Cal. Mar. 18","op":2,"ar":1,"by":{"1":"28","2":"19"}},{"t":"case","label":"Cleland v. Bronson Health Care Group, Inc.","cite":"917 F.2d 266","y":1990,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/917/266/","by":{"1":"27"}},{"t":"case","label":"Correa v. Hospital San Francisco","cite":"69 F.3d 1184","y":1995,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/69/1184/","by":{"1":"26","2":"31"}},{"t":"case","label":"English v. General Electric Company","cite":"496 U.S. 72","y":1990,"id":"1989/89-152","sc":1,"sum":"English's state-law claim for intentional infliction of emotional distress is not pre-empted by federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Gatewood v. Washington Healthcare Corp.","cite":"933 F.2d 1037","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/933/1037/","by":{"1":"26","2":"30, 32","4":"16"}},{"t":"case","label":"Goodman v. Sullivan","cite":"891 F.2d 449","y":1989,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/891/449/","by":{"1":"25","4":"15"}},{"t":"case","label":"Guardians Association v. Civil Service Commission of New York","cite":"463 U.S. 582","y":1983,"id":"1982/81-431","sc":1,"sum":"The judgment is affirmed. 633 F. 2d 232, affirmed. JUSTICE WHITE concluded that discriminatory intent is not an essential element of a Title VI violation. JUSTICE WHITE, joined by JUSTICE REHNQUIST, also concluded that a private plaintiff should recover only injunctive, noncompensatory relief for a defendant's unintentional violation of Title VI, that such relief should not include an award of constructive …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Hardy v. New York City Health & Hospital Corp.","cite":"164 F.3d 789","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/164/789/","by":{"1":"26, 36","2":"31-33, 37","3":"6"}},{"t":"case","label":"Holcomb v. Monahan","cite":"30 F.3d 116","y":1994,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/30/116/","by":{"1":"27"}},{"t":"case","label":"Jackson v. East Bay Hospital","cite":"246 F.3d 1248","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/246/1248/","by":{"1":"7"}},{"t":"case","label":"K Mart Corp. v. Cartier, Inc.","cite":"486 U.S. 281","y":1988,"id":"1987/86-495","sc":1,"sum":"The judgment is affirmed in part and reversed in part. 252 U. S. App. D. C. 342, 790 F. 2d 903, affirmed in part and reversed in part. JUSTICE KENNEDY delivered the opinion of the Court as to Parts I, II-A, and II-C, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Martindale v. Indiana University Health Bloomington, Inc.","cite":"39 F.4th 416","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/39/416/","by":{"1":"36"}},{"t":"case","label":"Maryland v. King","cite":"567 U.S. 1301","y":2012,"url":"https://supreme.justia.com/cases/federal/us/567/1301/","sc":1,"op":3,"by":{"1":"39"}},{"t":"case","label":"Morin v. Eastern Maine Medical Center","cite":"780 F. Supp. 2d 84","y":2010,"court":"D. Me.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/780/84/","by":{"1":"28"}},{"t":"case","label":"Nartey v. Franciscan Health Hospital","cite":"2 F.4th 1020","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/2/1020/","by":{"1":"27"}},{"t":"case","label":"New Motor Vehicle Board v. Orrin W. Fox Company","cite":"434 U.S. 1345","y":1977,"url":"https://supreme.justia.com/cases/federal/us/434/1345/","sc":1,"by":{"1":"39"}},{"t":"case","label":"New York v. Department of Health & Human Services","cite":"2022 WL 17974424","y":2022,"court":"2d Cir. Dec. 8","by":{"1":"28"}},{"t":"case","label":"New York v. Department of Health & Human Services","cite":"414 F. Supp. 3d 475","y":2019,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/414/475/","by":{"1":"28","2":"19"}},{"t":"case","label":"NFIB v. Department of Labor, Occupational Safety & Health Administration","cite":"595 U.S. 109","y":2022,"url":"https://supreme.justia.com/cases/federal/us/595/109/","sc":1,"by":{"1":"22, 39"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"op":3,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Planned Parenthood Arizona Inc. v. Betlach","cite":"727 F.3d 960","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/727/960/","by":{"1":"34"}},{"t":"case","label":"Ritten v. Lapeer Regional Medical Center","cite":"611 F. Supp. 2d 696","y":2009,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/611/696/","by":{"1":"28","2":"18, 19"}},{"t":"case","label":"Roberts v. Galen of Virginia, Inc.","cite":"525 U.S. 249","y":1999,"id":"1998/97-53","sc":1,"op":1,"sum":"The Court held that Section 1395dd(b) of the Emergency Medical Treatment and Active Labor Act contains no expressed or implied \"improper motive\" requirement. According o the Court's opinion, \"there is no question that the text of Section 1395dd(b) does not require an \"appropriate stabilization, nor can it reasonably be read to require an improper motive.\".","sumSrc":"Oyez","by":{"1":"9","2":"10, 28, 31","3":"7","4":"15"}},{"t":"case","label":"Texas v. Becerra","cite":"623 F. Supp. 3d 696","y":2022,"court":"N.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/623/696/","op":1,"by":{"1":"35","4":"11"}},{"t":"case","label":"Torretti v. Main Line Hospitals, Inc.","cite":"580 F.3d 168","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/580/168/","by":{"1":"26","2":"31","4":"16"}},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"United States v. Idaho","cite":"83 F.4th 1130","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/83/1130/","op":1,"by":{"1":"31"}},{"t":"case","label":"United States v. University Hospital, State University of New York at Stony Brook","cite":"729 F.2d 144","y":1984,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/729/144/","by":{"1":"25"}},{"t":"case","label":"Urban By & Through Urban v. King","cite":"43 F.3d 523","court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/43/523/","by":{"1":"27"}},{"t":"case","label":"Vickers v. Nash General Hospital, Inc.","cite":"78 F.3d 139","y":1996,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/78/139/","by":{"1":"26","2":"32","3":"9","4":"16"}},{"t":"case","label":"West Virginia v. E.P.A.","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"op":1,"by":{"1":"21, 22","2":"48-50","4":"4"}},{"t":"case","label":"Whole Woman’s Health v. Jackson","cite":"141 S. Ct. 2494","y":2021,"id":"2021/21-463","sc":1,"sum":"A pre-enforcement challenge under the Federal Constitution to Texas Senate Bill 8—the Texas Heartbeat Act—may proceed past the motion to dismiss stage against certain of the named defendants but not others; the order of the District Court is affirmed in part and reversed in part, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38"}},{"t":"case","label":"Winter v. Natural Resources Defense Council, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"sum":"The Court held that the standard for properly granting a preliminary injunction is not based on the \"possibility\" of irreparable harm to marine life, but rather that \"irreparable injury is likely\" in the absence of such an injunction.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"ar":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"1":"19, 23, 36","4":"3, 14"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"1":"2"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"1":"1"}},{"t":"usc","label":"28 U.S.C. § 1345","url":"https://www.law.cornell.edu/uscode/text/28/1345","by":{"1":"1"}},{"t":"usc","label":"28 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/28/2101","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1395","url":"https://www.law.cornell.edu/uscode/text/42/1395","stext":{"head":"§1395. Prohibition against any Federal interference","paras":[[0,"Nothing in this subchapter shall be construed to authorize any Federal officer or employee to exercise any supervision or control over the practice of medicine or the manner in which medical services are provided, or over the selection, tenure, or compensation of any officer or employee of any institution, agency, or person providing health services; or to exercise any supervision or control over the administration or operation of any such institution, agency, or person."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":4,"head":"§1395. Prohibition against any Federal interference","tname":"The Public Health and Welfare","by":{"1":"11, 20","2":"29","4":"1, 5, 6"}},{"t":"usc","label":"42 U.S.C. § 1395dd","url":"https://www.law.cornell.edu/uscode/text/42/1395dd","subs":["(b)","(b)(1)","(b)(1)(A)","(b)(2)","(c)(1)","(c)(1)(A)(ii)","(c)(2)(A)","(d)(1)","(d)(2)","(d)(2)(A)","(d)(2)(B)","(e)(1)(A)(1988)","(e)(1)(A)","(e)(1)(A)(i)","(e)(1)(B)","(e)(1)(B)(ii)","(e)(3)","(e)(3)(A)","(e)(4)","(i)"],"stext":{"head":"§1395dd. Examination and treatment for emergency medical conditions and women in labor","paras":[[0,"(a) Medical screening requirement"],[0,"In the case of a hospital that has a hospital emergency department, if any individual (whether or not eligible for benefits under this subchapter) comes to the emergency department and a request is made on the individual's behalf for examination or treatment for a medical condition, the hospital must provide for an appropriate medical screening examination within the capability of the hospital's emergency department, including ancillary services routinely available to the emergency department, to determine whether or not an emergency medical condition (within the meaning of subsection (e)(1)) exists."],[0,"(b) Necessary stabilizing treatment for emergency medical conditions and labor"],[0,"(1) In general"],[1,"If any individual (whether or not eligible for benefits under this subchapter) comes to a hospital and the hospital determines that the individual has an emergency medical condition, the hospital must provide either—"],[2,"(A) within the staff and facilities available at the hospital, for such further medical examination and such treatment as may be required to stabilize the medical condition, or"],[2,"(B) for transfer of the individual to another medical facility in accordance with subsection (c)."],[0,"(2) Refusal to consent to treatment"],[1,"A hospital is deemed to meet the requirement of paragraph (1)(A) with respect to an individual if the hospital offers the individual the further medical examination and treatment described in that paragraph and informs the individual (or a person acting on the individual's behalf) of the risks and benefits to the individual of such examination and treatment, but the individual (or a person acting on the individual's behalf) refuses to consent to the examination and treatment. The hospital shall take all reasonable steps to secure the individual's (or person's) written informed consent to refuse such examination and treatment."],[0,"(3) Refusal to consent to transfer"],[1,"A hospital is deemed to meet the requirement of paragraph (1) with respect to an individual if the hospital offers to transfer the individual to another medical facility in accordance with subsection (c) and informs the individual (or a person acting on the individual's behalf) of the risks and benefits to the individual of such transfer, but the individual (or a person acting on the individual's behalf) refuses to consent to the transfer. The hospital shall take all reasonable steps to secure the individual's (or person's) written informed consent to refuse such transfer."],[0,"(c) Restricting transfers until individual stabilized"],[0,"(1) Rule"],[1,"If an individual at a hospital has an emergency medical condition which has not been stabilized (within the meaning of subsection (e)(3)(B)), the hospital may not transfer the individual unless—"],[2,"(A)(i) the individual (or a legally responsible person acting on the individual's behalf) after being informed of the hospital's obligations under this section and of the risk of transfer, in writing requests transfer to another medical facility,"],[2,"(ii) a physician (within the meaning of section 1395x(r)(1) of this title) has signed a certification that 1 based upon the information available at the time of transfer, the medical benefits reasonably expected from the provision of appropriate medical treatment at another medical facility outweigh the increased risks to the individual and, in the case of labor, to the unborn child from effecting the transfer, or"],[2,"(iii) if a physician is not physically present in the emergency department at the time an individual is transferred, a qualified medical person (as defined by the Secretary in regulations) has signed a certification described in clause (ii) after a physician (as defined in section 1395x(r)(1) of this title), in consultation with the person, has made the determination described in such clause, and subsequently countersigns the certification; and"],[2,"(B) the transfer is an appropriate transfer (within the meaning of paragraph (2)) to that facility."],[1,"A certification described in clause (ii) or (iii) of subparagraph (A) shall include a summary of the risks and benefits upon which the certification is based."],[0,"(2) Appropriate transfer"],[1,"An appropriate transfer to a medical facility is a transfer—"],[2,"(A) in which the transferring hospital provides the medical treatment within its capacity which minimizes the risks to the individual's health and, in the case of a woman in labor, the health of the unborn child;"],[2,"(B) in which the receiving facility—"],[3,"(i) has available space and qualified personnel for the treatment of the individual, and"],[3,"(ii) has agreed to accept transfer of the individual and to provide appropriate medical treatment;"],[2,"(C) in which the transferring hospital sends to the receiving facility all medical records (or copies thereof), related to the emergency condition for which the individual has presented, available at the time of the transfer, including records related to the individual's emergency medical condition, observations of signs or symptoms, preliminary diagnosis, treatment provided, results of any tests and the informed written consent or certification (or copy thereof) provided under paragraph (1)(A), and the name and address of any on-call physician (described in subsection (d)(1)(C)) who has refused or failed to appear within a reasonable time to provide necessary stabilizing treatment;"],[2,"(D) in which the transfer is effected through qualified personnel and transportation equipment, as required including the use of necessary and medically appropriate life support measures during the transfer; and"],[2,"(E) which meets such other requirements as the Secretary may find necessary in the interest of the health and safety of individuals transferred."],[0,"(d) Enforcement"],[0,"(1) Civil money penalties"],[1,"(A) A participating hospital that negligently violates a requirement of this section is subject to a civil money penalty of not more than $50,000 (or not more than $25,000 in the case of a hospital with less than 100 beds) for each such violation. The provisions of section 1320a–7a of this title (other than subsections (a) and (b)) shall apply to a civil money penalty under this subparagraph in the same manner as such provisions apply with respect to a penalty or proceeding under section 1320a–7a(a) of this title."],[1,"(B) Subject to subparagraph (C), any physician who is responsible for the examination, treatment, or transfer of an individual in a participating hospital, including a physician on-call for the care of such an individual, and who negligently violates a requirement of this section, including a physician who—"],[2,"(i) signs a certification under subsection (c)(1)(A) that the medical benefits reasonably to be expected from a transfer to another facility outweigh the risks associated with the transfer, if the physician knew or should have known that the benefits did not outweigh the risks, or"],[2,"(ii) misrepresents an individual's condition or other information, including a hospital's obligations under this section,"],[1,"is subject to a civil money penalty of not more than $50,000 for each such violation and, if the violation is gross and flagrant or is repeated, to exclusion from participation in this subchapter and State health care programs. The provisions of section 1320a–7a of this title (other than the first and second sentences of subsection (a) and subsection (b)) shall apply to a civil money penalty and exclusion under this subparagraph in the same manner as such provisions apply with respect to a penalty, exclusion, or proceeding under section 1320a–7a(a) of this title."],[1,"(C) If, after an initial examination, a physician determines that the individual requires the services of a physician listed by the hospital on its list of on-call physicians (required to be maintained under section 1395cc(a)(1)(I) of this title) and notifies the on-call physician and the on-call physician fails or refuses to appear within a reasonable period of time, and the physician orders the transfer of the individual because the physician determines that without the services of the on-call physician the benefits of transfer outweigh the risks of transfer, the physician authorizing the transfer shall not be subject to a penalty under subparagraph (B). However, the previous sentence shall not apply to the hospital or to the on-call physician who failed or refused to appear."],[0,"(2) Civil enforcement"],[0,"(A) Personal harm"],[2,"Any individual who suffers personal harm as a direct result of a participating hospital's violation of a requirement of this section may, in a civil action against the participating hospital, obtain those damages available for personal injury under the law of the State in which the hospital is located, and such equitable relief as is appropriate."],[0,"(B) Financial loss to other medical facility"],[2,"Any medical facility that suffers a financial loss as a direct result of a participating hospital's violation of a requirement of this section may, in a civil action against the participating hospital, obtain those damages available for financial loss, under the law of the State in which the hospital is located, and such equitable relief as is appropriate."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395dd?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1395dd. Examination and treatment for emergency medical conditions and women in labor","tname":"The Public Health and Welfare","by":{"1":"7–11, 17, 20–21, 23, 25, 28, 32, 34, 41","2":"2, 5, 5, 5, 5, 5, 5, 5, 5, 5, 42, 42, 42, 29, 29, 29, 29, 29, 29, 29, 29, 29","4":"1, 6, 17, 18, 19, 20, 24"}},{"t":"law","label":"Pub. L. No. 117-328","url":"https://www.govinfo.gov/link/plaw/117/public/328","by":{"1":"35, 34"}},{"t":"law","label":"Pub. L. No. 101-239","url":"https://www.govinfo.gov/link/statute/103/2106","by":{"1":"32, 37","2":"42"}},{"t":"reg","label":"Further Efforts To Protect Access to Reproductive Healthcare Services, Presidential Memorandum, 88 Fed. Reg. 4895","url":"https://www.govinfo.gov/link/fr/88/4895","by":{"1":"12"}},{"t":"reg","label":"Securing Access to Reproductive and Other Healthcare Services, Exec. Order No. 14079, 87 Fed. Reg. 49505","url":"https://www.govinfo.gov/link/fr/87/49505","by":{"1":"12"}},{"t":"case","label":"Arrington v. Wong","cite":"237 F.3d 1066","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/237/1066/","by":{"2":"21"}},{"t":"case","label":"Bennett v. Arkansas","cite":"485 U.S. 395","y":1988,"id":"1987/86-6124","sc":1,"op":1,"sum":"The Arkansas statute violates the Supremacy Clause. There is no \"implied exception\" to the express language of § 407(a) and its clear intent that Social Security benefits not be attachable, even though the State provides for all of petitioner's needs. The State is not a statutorily intended beneficiary of petitioner's Social Security benefits. Rose v. Rose, 481 U. S. 619, distinguished. 290 Ark. 47, 716 S. W. 2d …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46","3":"25"}},{"t":"case","label":"Bostock v. Clayton County","cite":"590 U.S. 644","y":2020,"id":"2019/17-1618","sc":1,"ar":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Brnovich v. DNC","cite":"141 S. Ct. 2321","y":2021,"id":"2020/19-1257","sc":1,"sum":"Arizona’s challenged voting regulations governing precinct-based election-day voting (rejecting ballots cast in the wrong precinct) and early mail-in voting (making it a crime for anyone other than an authorized proxy to possess the early ballot of another voter) do not violate §2 of the Voting Rights Act of 1965; Arizona House Bill 2023 (enacting the early mail-in voting regulations) was not enacted with a racially discriminatory purpose.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"49"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"op":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12, 30"}},{"t":"case","label":"Coventry Health Care of Missouri, Inc. v. Nevils","cite":"581 U.S. 87","y":2017,"id":"2016/16-149","sc":1,"op":1,"ar":1,"sum":"The Court determined that the Federal Employees Health Benefits Act (FEHBA) preempts state laws that prohibit insurance companies from claiming the proceeds of personal injury settlements pursuant to their contracts, and the express preemption clause of the FEHBA does not violate the Supremacy Clause.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"op":1,"sum":"The Court held that 18 U.S.C. Section 924(c)(1)(A)(iii) does not require proof of intent to discharge a firearm in order to enhance a sentence.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Eberhardt v. City of Los Angeles","cite":"62 F.3d 1253","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/62/1253/","by":{"2":"31"}},{"t":"case","label":"Lawrence Cnty. v. Lead-Deadwood Sch. Dist. No. 40-1","cite":"469 U.S. 256","y":1985,"id":"1984/83-240","sc":1,"op":1,"sum":"The state statute is invalid under the Supremacy Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46","3":"25"}},{"t":"case","label":"Oneok, Inc. v. Learjet, Inc.","cite":"575 U.S. 373","y":2015,"id":"2014/13-271","sc":1,"sum":"The Court held that the Natural Gas Act does not pre-empt state law claims brought by litigants who purchased gas in retail transactions.","sumSrc":"Oyez","by":{"2":"20, 47"}},{"t":"case","label":"Philko Aviation, Inc. v. Shacket","cite":"462 U.S. 406","y":1983,"id":"1982/82-342","sc":1,"sum":"State laws, such as the Illinois law, allowing undocumented or unrecorded transfers of interests in aircraft to affect innocent third parties are pre-empted by the federal Act. Although if § 508(c) were interpreted literally in accordance with the federal Act's definition of \"conveyance\"--\"a bill of sale, contract of conditional sale, mortgage, assignment of mortgage, or other instrument affecting title to, or …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Planned Parenthood Ariz., Inc. v. Brnovich","cite":"524 P.3d 262","y":2022,"court":"Ariz. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/524/262/","by":{"2":"6, 48"}},{"t":"case","label":"Power v. Arlington Hosp. Ass’n","cite":"42 F.3d 851","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/42/851/","by":{"2":"32","3":"6"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Southland Corp. v. Keating","cite":"465 U.S. 1","y":1984,"id":"1983/82-500","sc":1,"sum":"Appellant Southland Corp. (hereafter appellant) is the owner and franchisor of 7-Eleven convenience stores. Appellees are 7-Eleven franchisees. Each franchise agreement between appellant and appellees contains a clause requiring arbitration of any controversy or claim arising out of or relating to the agreement or breach thereof. Several of the appellees filed individual actions against appellant in California …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Thomas v. Christ Hosp. & Med. Ctr.","cite":"328 F.3d 890","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/328/890/","by":{"2":"30","4":"16"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"2":"36, 45, 47"}},{"t":"usc","label":"42 U.S.C. § 13955dd","url":"https://www.law.cornell.edu/uscode/text/42/13955dd","subs":["(a)"],"by":{"2":"5"}},{"t":"law","label":"Patient Protection and Affordable Care Act, Pub. L. No. 111-148","url":"https://www.govinfo.gov/link/plaw/111/public/148","by":{"2":"20"}},{"t":"usc","label":"1 U.S.C. § 8","url":"https://www.law.cornell.edu/uscode/text/1/8","subs":["(a)"],"stext":{"head":"§8. \"Person\", \"human being\", \"child\", and \"individual\" as including born-alive infant","paras":[[0,"(a) In determining the meaning of any Act of Congress, or of any ruling, regulation, or interpretation of the various administrative bureaus and agencies of the United States, the words \"person\", \"human being\", \"child\", and \"individual\", shall include every infant member of the species homo sapiens who is born alive at any stage of development."],[0,"(b) As used in this section, the term \"born alive\", with respect to a member of the species homo sapiens, means the complete expulsion or extraction from his or her mother of that member, at any stage of development, who after such expulsion or extraction breathes or has a beating heart, pulsation of the umbilical cord, or definite movement of voluntary muscles, regardless of whether the umbilical cord has been cut, and regardless of whether the expulsion or extraction occurs as a result of natural or induced labor, cesarean section, or induced abortion."],[0,"(c) Nothing in this section shall be construed to affirm, deny, expand, or contract any legal status or legal right applicable to any member of the species homo sapiens at any point prior to being \"born alive\" as defined in this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/8?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§8. \"Person\", \"human being\", \"child\", and \"individual\" as including born-alive infant","tname":"General Provisions","by":{"2":"41"}},{"t":"usc","label":"7 U.S.C. § 2156","url":"https://www.law.cornell.edu/uscode/text/7/2156","by":{"2":"37"}},{"t":"usc","label":"10 U.S.C. § 1093","url":"https://www.law.cornell.edu/uscode/text/10/1093","by":{"2":"40"}},{"t":"usc","label":"15 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/15/1225","by":{"2":"37"}},{"t":"usc","label":"16 U.S.C. § 544l","url":"https://www.law.cornell.edu/uscode/text/16/544l","subs":["(e)(5)"],"by":{"2":"37"}},{"t":"usc","label":"16 U.S.C. § 3507","url":"https://www.law.cornell.edu/uscode/text/16/3507","by":{"2":"37"}},{"t":"usc","label":"20 U.S.C. § 1688","url":"https://www.law.cornell.edu/uscode/text/20/1688","by":{"2":"40"}},{"t":"usc","label":"22 U.S.C. § 5453","url":"https://www.law.cornell.edu/uscode/text/22/5453","subs":["(b)"],"by":{"2":"40"}},{"t":"usc","label":"22 U.S.C. § 7704","url":"https://www.law.cornell.edu/uscode/text/22/7704","subs":["(e)(4)"],"by":{"2":"40"}},{"t":"usc","label":"25 U.S.C. § 1676","url":"https://www.law.cornell.edu/uscode/text/25/1676","subs":["(a)"],"by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 238n","url":"https://www.law.cornell.edu/uscode/text/42/238n","by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 280h-5","url":"https://www.law.cornell.edu/uscode/text/42/280h-5","subs":["(a)(3)(C)"],"by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 300a-6","url":"https://www.law.cornell.edu/uscode/text/42/300a-6","by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 300a-7","url":"https://www.law.cornell.edu/uscode/text/42/300a-7","by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 300a-8","url":"https://www.law.cornell.edu/uscode/text/42/300a-8","by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 300z-10","url":"https://www.law.cornell.edu/uscode/text/42/300z-10","subs":["(a)"],"by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 1395w-25","url":"https://www.law.cornell.edu/uscode/text/42/1395w-25","subs":["(a)(2)(E)(iv)"],"by":{"2":"46"}},{"t":"usc","label":"42 U.S.C. § 1395w-26","url":"https://www.law.cornell.edu/uscode/text/42/1395w-26","subs":["(b)(3)"],"by":{"2":"46"}},{"t":"usc","label":"42 U.S.C. § 1395w-104","url":"https://www.law.cornell.edu/uscode/text/42/1395w-104","subs":["(e)(5)"],"by":{"2":"46"}},{"t":"usc","label":"42 U.S.C. § 1395w-112","url":"https://www.law.cornell.edu/uscode/text/42/1395w-112","subs":["(g)"],"by":{"2":"46"}},{"t":"usc","label":"42 U.S.C. § 1395cc","url":"https://www.law.cornell.edu/uscode/text/42/1395cc","subs":["(a)(1)(I)(i)","(b)"],"by":{"2":"4, 45, 5"}},{"t":"usc","label":"42 U.S.C. § 1397ee","url":"https://www.law.cornell.edu/uscode/text/42/1397ee","subs":["(c)(7)(A)"],"by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 18023","url":"https://www.law.cornell.edu/uscode/text/42/18023","subs":["(a)","(b)","(d)"],"stext":{"head":"§18023. Special rules","paras":[[0,"(a) State opt-out of abortion coverage"],[0,"(1) In general"],[1,"A State may elect to prohibit abortion coverage in qualified health plans offered through an Exchange in such State if such State enacts a law to provide for such prohibition."],[0,"(2) Termination of opt out"],[1,"A State may repeal a law described in paragraph (1) and provide for the offering of such services through the Exchange."],[0,"(b) Special rules relating to coverage of abortion services"],[0,"(1) Voluntary choice of coverage of abortion services"],[0,"(A) In general"],[2,"Notwithstanding any other provision of this title 1 (or any amendment made by this title)— 1"],[3,"(i) nothing in this title 1 (or any amendment made by this title),1 shall be construed to require a qualified health plan to provide coverage of services described in subparagraph (B)(i) or (B)(ii) as part of its essential health benefits for any plan year; and"],[3,"(ii) subject to subsection (a), the issuer of a qualified health plan shall determine whether or not the plan provides coverage of services described in subparagraph (B)(i) or (B)(ii) as part of such benefits for the plan year."],[0,"(B) Abortion services"],[0,"(i) Abortions for which public funding is prohibited"],[3,"The services described in this clause are abortions for which the expenditure of Federal funds appropriated for the Department of Health and Human Services is not permitted, based on the law as in effect as of the date that is 6 months before the beginning of the plan year involved."],[0,"(ii) Abortions for which public funding is allowed"],[3,"The services described in this clause are abortions for which the expenditure of Federal funds appropriated for the Department of Health and Human Services is permitted, based on the law as in effect as of the date that is 6 months before the beginning of the plan year involved."],[0,"(2) Prohibition on the use of Federal funds"],[0,"(A) In general"],[2,"If a qualified health plan provides coverage of services described in paragraph (1)(B)(i), the issuer of the plan shall not use any amount attributable to any of the following for purposes of paying for such services:"],[3,"(i) The credit under section 36B of title 26 (and the amount (if any) of the advance payment of the credit under section 18082 of this title)."],[3,"(ii) Any cost-sharing reduction under section 18071 of this title (and the amount (if any) of the advance payment of the reduction under section 18082 of this title)."],[0,"(B) Establishment of allocation accounts"],[2,"In the case of a plan to which subparagraph (A) applies, the issuer of the plan shall—"],[3,"(i) collect from each enrollee in the plan (without regard to the enrollee's age, sex, or family status) a separate payment for each of the following:"],[4,"(I) an amount equal to the portion of the premium to be paid directly by the enrollee for coverage under the plan of services other than services described in paragraph (1)(B)(i) (after reduction for credits and cost-sharing reductions described in subparagraph (A)); and"],[4,"(II) an amount equal to the actuarial value of the coverage of services described in paragraph (1)(B)(i), and"],[3,"(ii) shall 2 deposit all such separate payments into separate allocation accounts as provided in subparagraph (C)."],[2,"In the case of an enrollee whose premium for coverage under the plan is paid through employee payroll deposit, the separate payments required under this subparagraph shall each be paid by a separate deposit."],[0,"(C) Segregation of funds"],[0,"(i) In general"],[3,"The issuer of a plan to which subparagraph (A) applies shall establish allocation accounts described in clause (ii) for enrollees receiving amounts described in subparagraph (A)."],[0,"(ii) Allocation accounts"],[3,"The issuer of a plan to which subparagraph (A) applies shall deposit—"],[4,"(I) all payments described in subparagraph (B)(i)(I) into a separate account that consists solely of such payments and that is used exclusively to pay for services other than services described in paragraph (1)(B)(i); and"],[4,"(II) all payments described in subparagraph (B)(i)(II) into a separate account that consists solely of such payments and that is used exclusively to pay for services described in paragraph (1)(B)(i)."],[0,"(D) Actuarial value"],[0,"(i) In general"],[3,"The issuer of a qualified health plan shall estimate the basic per enrollee, per month cost, determined on an average actuarial basis, for including coverage under the qualified health plan of the services described in paragraph (1)(B)(i)."],[0,"(ii) Considerations"],[3,"In making such estimate, the issuer—"],[4,"(I) may take into account the impact on overall costs of the inclusion of such coverage, but may not take into account any cost reduction estimated to result from such services, including prenatal care, delivery, or postnatal care;"],[4,"(II) shall estimate such costs as if such coverage were included for the entire population covered; and"],[4,"(III) may not estimate such a cost at less than $1 per enrollee, per month."],[0,"(E) Ensuring compliance with segregation requirements"],[0,"(i) In general"],[3,"Subject to clause (ii), State health insurance commissioners shall ensure that health plans comply with the segregation requirements in this subsection through the segregation of plan funds in accordance with applicable provisions of generally accepted accounting requirements, circulars on funds management of the Office of Management and Budget, and guidance on accounting of the Government Accountability Office."],[0,"(ii) Clarification"],[3,"Nothing in clause (i) shall prohibit the right of an individual or health plan to appeal such action in courts of competent jurisdiction."],[0,"(3) Rules relating to notice"],[0,"(A) Notice"],[2,"A qualified health plan that provides for coverage of the services described in paragraph (1)(B)(i) shall provide a notice to enrollees, only as part of the summary of benefits and coverage explanation, at the time of enrollment, of such coverage."],[0,"(B) Rules relating to payments"],[2,"The notice described in subparagraph (A), any advertising used by the issuer with respect to the plan, any information provided by the Exchange, and any other information specified by the Secretary shall provide information only with respect to the total amount of the combined payments for services described in paragraph (1)(B)(i) and other services covered by the plan."],[0,"(4) No discrimination on basis of provision of abortion"],[1,"No qualified health plan offered through an Exchange may discriminate against any individual health care provider or health care facility because of its unwillingness to provide, pay for, provide coverage of, or refer for abortions 3"],[0,"(c) Application of State and Federal laws regarding abortion"],[0,"(1) No preemption of State laws regarding abortion"],[1,"Nothing in this Act shall be construed to preempt or otherwise have any effect on State laws regarding the prohibition of (or requirement of) coverage, funding, or procedural requirements on abortions, including parental notification or consent for the performance of an abortion on a minor."],[0,"(2) No effect on Federal laws regarding abortion"],[0,"(A) 4 In general"],[2,"Nothing in this Act shall be construed to have any effect on Federal laws regarding—"],[3,"(i) conscience protection;"],[3,"(ii) willingness or refusal to provide abortion; and"],[3,"(iii) discrimination on the basis of the willingness or refusal to provide, pay for, cover, or refer for abortion or to provide or participate in training to provide abortion."],[0,"(3) No effect on Federal civil rights law"],[1,"Nothing in this subsection shall alter the rights and obligations of employees and employers under title VII of the Civil Rights Act of 1964 [42 U.S.C. 2000e et seq.]."],[0,"(d) Application of emergency services laws"],[0,"Nothing in this Act shall be construed to relieve any health care provider from providing emergency services as required by State or Federal law, including section 1395dd of this title (popularly known as \"EMTALA\")."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/18023?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§18023. Special rules","tname":"The Public Health and Welfare","by":{"2":"19, 19, 20","4":"13, 14"}},{"t":"usc","label":"42 U.S.C. § 2996f","url":"https://www.law.cornell.edu/uscode/text/42/2996f","subs":["(b)(8)"],"by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 12584a","url":"https://www.law.cornell.edu/uscode/text/42/12584a","subs":["(a)(9)"],"by":{"2":"40"}},{"t":"usc","label":"43 U.S.C. § 1600g","url":"https://www.law.cornell.edu/uscode/text/43/1600g","by":{"2":"37"}},{"t":"reg","label":"73 Fed. Reg. 78,072","url":"https://www.govinfo.gov/link/fr/73/78072","by":{"2":"17","4":"10"}},{"t":"reg","label":"84 Fed. Reg. 23,170","url":"https://www.govinfo.gov/link/fr/84/23170","by":{"2":"17","4":"10"}},{"t":"case","label":"Bates v. United States","cite":"522 U.S. 23","y":1997,"id":"1997/96-7185","sc":1,"sum":"The Court held that the specific intent to injure or defraud someone, whether the United States or another, is not an element of the misapplication of funds proscribed by section 1097(a).","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"Bowsher v. Merck & Co.","cite":"460 U.S. 824","y":1983,"id":"1982/81-1273","sc":1,"sum":"The Comptroller General may inspect Merck's records of direct costs but not records of indirect costs.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4"}},{"t":"case","label":"Carlisle v. Frisbie Mem’l Hosp.","cite":"888 A.2d 405","y":2005,"court":"N.H.","url":"https://www.courtlistener.com/c/A.2d/888/405/","by":{"3":"6"}},{"t":"case","label":"Dunlap v. Garner","cite":"903 P.2d 1296","y":1994,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/903/1296/","by":{"3":"22"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"Green v. Touro Infirmary","cite":"992 F.2d 537","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/992/537/","by":{"3":"8"}},{"t":"case","label":"Kozlowski v. Rush","cite":"828 P.2d 854","y":1992,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/828/854/","by":{"3":"22"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"R.A.V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"sum":"The Court found a Minnesota ordinance violated the First Amendment because the ordinance was overly broad in the content-based speech it prohibited.","sumSrc":"Oyez","by":{"3":"19, 22"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4"}},{"t":"case","label":"Reid v. Indianapolis Osteopathic Med. Hosp., Inc.","cite":"709 F. Supp. 853","y":1989,"court":"S.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp./709/853/","by":{"3":"6"}},{"t":"case","label":"Rice v. Norman Williams Co.","cite":"458 U.S. 654","y":1982,"id":"1981/80-1012","sc":1,"sum":"A provision of California's alcoholic beverage laws states that a \"licensed importer shall not purchase or accept delivery of any brand of distilled spirits unless he is designated as an authorized importer of such brand by the brand owner or his authorized agent\" (designation statute). The statute apparently was enacted in response to the perceived extraterritorial effects of Oklahoma's \"open wholesaling\" statutes, …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4, 14"}},{"t":"case","label":"Sprietsma v. Mercury Marine","cite":"537 U.S. 51","y":2002,"id":"2002/01-706","sc":1,"sum":"The Court held 8-0 that neither the text nor the intent of the FBSA preempts Sprietsma's common law claims, either explicitly or implicitly.","sumSrc":"Oyez","by":{"3":"2"}},{"t":"case","label":"Woodfield v. Bd. of Pro. Discipline of Idaho State Bd. of Med.","cite":"905 P.2d 1047","y":1995,"court":"Idaho App.","url":"https://www.courtlistener.com/c/P.2d/905/1047/","by":{"3":"22"}},{"t":"reg","label":"42 C.F.R. § 489.24","url":"https://www.ecfr.gov/current/title-42/section-489.24","subs":["(d)(2)(i)"],"by":{"3":"8"}},{"t":"reg","label":"68 Fed. Reg. 53,222","url":"https://www.govinfo.gov/link/fr/68/53222","by":{"3":"5, 6, 12"}},{"t":"reg","label":"Exec. Order No. 13,535, 75 Fed. Reg. 15,599","url":"https://www.govinfo.gov/link/fr/75/15599","by":{"3":"19"}},{"t":"case","label":"Cruzan v. Director, Missouri Department of Health","cite":"497 U.S. 261","y":1990,"id":"1989/88-1503","sc":1,"sum":"The Court held that a Missouri state hospital had the right to keep a patient in a vegetative state alive, despite the wishes of the patient's parents, due to a lack of otherwise \"clear and convincing\" wishes on the part of the patient.","sumSrc":"Oyez","by":{"4":"19"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"sum":"In a unanimous ruling written by Justice William Rehnquist, the Court held that claims of excessive force used by government officials are properly analyzed under the Fourth Amendment’s “objective reasonableness” standard. The Court vacated the directed verdict and remanded the case to the district court to be decided by that standard.","sumSrc":"Oyez","by":{"4":"20"}},{"t":"case","label":"Phillips v. Hillcrest Medical Center","cite":"244 F.3d 790","y":2001,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/244/790/","by":{"4":"17"}},{"t":"case","label":"United States v. Southwestern Cable Company","cite":"392 U.S. 157","y":1968,"id":"1967/363","sc":1,"sum":"Community antenna television (CATV) systems receive television broadcast signals, amplify them, transmit them by cable or microwave, and distribute them by wire to their subscribers' receivers. In 1959 the Federal Communications Commission (FCC), although it found CATV \"related to interstate transmission,\" stated that it \"did not intend to regulate CATV,\" and that it preferred to recommend legislation.which would …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"14"}},{"t":"usc","label":"42 U.S.C. § 1320c-3","url":"https://www.law.cornell.edu/uscode/text/42/1320c-3","by":{"4":"20, 21"}},{"t":"usc","label":"42 U.S.C. § 1395aa","url":"https://www.law.cornell.edu/uscode/text/42/1395aa","by":{"4":"11"}},{"t":"law","label":"Pub. L. No. 99-272","url":"https://www.govinfo.gov/link/statute/100/82","by":{"4":"18"}},{"t":"reg","label":"42 C.F.R. § 482.11","url":"https://www.ecfr.gov/current/title-42/section-482.11","by":{"4":"2, 6"}},{"t":"reg","label":"Medicare Program, 59 Fed. Reg. 32,086","url":"https://www.govinfo.gov/link/fr/59/32086","by":{"4":"24"}}]};